import test from 'node:test';import assert from 'node:assert/strict';import {pathfind,blocked,cellAt} from '../src/navigation.js';import {objects,materials,roster,modes} from '../src/data.js';
test('every destination reachable from home and each other, without crossing pond',()=>{for(const a of objects.filter(o=>o.zone==='grounds'))for(const b of objects.filter(o=>o.zone==='grounds')){const p=pathfind([a.x,a.y],[b.x,b.y]);if(a!==b)assert.ok(p.length,`${a.id} to ${b.id}`);for(const xy of p)assert.equal(blocked(...cellAt(...xy)),false);if(p.length)assert.deepEqual(cellAt(...p.at(-1)),cellAt(b.x,b.y));}});
test('pond rejected and offscreen destinations clamped',()=>{assert.deepEqual(pathfind([130,460],[550,200]),[]);assert.ok(pathfind([130,460],[-200,900]).length)});
test('three geology discoveries and canonical roster remain configurable',()=>{assert.deepEqual(materials.map(m=>m.id),['quartz','iron','fossil']);assert.equal(roster.length,8);assert.equal(Object.keys(modes).length,7);for(const m of materials)assert.ok(m.icon&&m.diagram&&m.text)});
